(() => {
  const DAY = 86400000;
  const DEFAULT_START_DATE = '2026-09-01';
  const defaultSettings = { totalPages: 604, memorizedPages: 160, lastMemorizedPage: 160, currentSurah: 'نهاية الجزء الثامن تقريبًا', startDate: DEFAULT_START_DATE, memorizationDays: [0, 1, 2, 3, 4], newPagesPerDay: 1, dailyReviewPages: 4, morningMinutes: 60, eveningMinutes: 60, reviewIntervals: { excellent: 14, good: 7, weak: 3, repeat: 1 }, mushafEdition: 'مصحف المدينة 604 صفحة', allowExtraReviews: false, reminders: { morning: false, evening: false, overdue: false } };
  const labels = { excellent: 'ممتاز', good: 'جيد', weak: 'ضعيف', repeat: 'يحتاج إعادة' };
  const KEY = 'quran-memorization-app-v1';
  const starts = [1,22,42,62,82,102,121,142,162,182,202,222,242,262,282,302,322,342,362,382,402,422,442,462,482,502,522,542,562,582];
  const parseDate = (s) => new Date(`${s}T00:00:00Z`);
  const formatDate = (d) => d.toISOString().slice(0, 10);
  const addDays = (s, n) => formatDate(new Date(parseDate(s).getTime() + n * DAY));
  const daysBetween = (a, b) => Math.floor((parseDate(b).getTime() - parseDate(a).getTime()) / DAY);
  const weekday = (s) => parseDate(s).getUTCDay();
  const arDate = (s) => new Intl.DateTimeFormat('ar-SA-u-ca-gregory', { dateStyle: 'full' }).format(parseDate(s));
  const hijriDate = (s) => new Intl.DateTimeFormat('ar-SA-u-ca-islamic-umalqura', { dateStyle: 'medium' }).format(parseDate(s));
  function getPageMeta(page) { const juz = Math.min(30, Math.max(1, starts.findIndex((s, i) => page >= s && (starts[i + 1] === undefined || page < starts[i + 1])) + 1)); return { page, surah: page <= 1 ? 'الفاتحة' : page <= 49 ? 'البقرة' : page <= 76 ? 'آل عمران' : page <= 106 ? 'النساء' : page <= 127 ? 'المائدة' : `بيانات السورة قابلة للاستبدال للصفحة ${page}`, juz, hizb: Math.ceil(juz * 2 - 1 + (page - starts[juz - 1]) / 10), quarter: 'تقريبي' }; }
  const quran = { getPage: getPageMeta, getTrustedSourceName: () => 'بيانات وصفية محلية قابلة للاستبدال؛ لا تحتوي نص القرآن أو صور المصحف' };
  const audio = { getAudioUrl: () => undefined, getSourceName: () => 'لا يوجد مصدر صوت مدمج؛ يمكن ربط مصدر موثوق لاحقًا' };
  function createInitialState(settings = defaultSettings) { const pages = {}; for (let p = 1; p <= settings.lastMemorizedPage; p++) pages[p] = { page: p, firstMemorized: settings.startDate, reviewCount: 0, nextReview: settings.startDate }; return { settings: { ...settings, reviewIntervals: { ...settings.reviewIntervals }, memorizationDays: [...settings.memorizationDays] }, pages, history: [], postponedDates: [], started: false, theme: 'light' }; }
  function loadState() { try { const raw = localStorage.getItem(KEY); return raw ? JSON.parse(raw) : createInitialState(); } catch { return createInitialState(); } }
  function saveState(s) { try { localStorage.setItem(KEY, JSON.stringify(s)); } catch { /* local storage can be disabled; keep in memory */ } }
  function calculateRemainingPages(s) { return Math.max(0, s.totalPages - s.lastMemorizedPage); }
  function calculateProgress(s) { const memorized = Math.min(s.totalPages, s.lastMemorizedPage); return { memorizedPages: memorized, remainingPages: calculateRemainingPages(s), percent: Math.round((memorized / s.totalPages) * 1000) / 10, completedJuz: Math.floor(memorized / (s.totalPages / 30)) }; }
  function isMemorizationDay(date, s) { return s.memorizationDays.includes(weekday(date)); }
  function calculateEstimatedCompletionDate(state, from = state.settings.startDate) { let date = from, remaining = calculateRemainingPages(state.settings), guard = 5000; while (remaining > 0 && guard-- > 0) { if (isMemorizationDay(date, state.settings) && !state.postponedDates.includes(date)) remaining -= state.settings.newPagesPerDay; if (remaining > 0) date = addDays(date, 1); } return date; }
  function nextNewPages(state, date) { if (!isMemorizationDay(date, state.settings)) return []; const start = state.settings.lastMemorizedPage + 1; return Array.from({ length: state.settings.newPagesPerDay }, (_, i) => start + i).filter(p => p <= state.settings.totalPages); }
  const priority = { repeat: 0, weak: 1, good: 3, excellent: 4 };
  function getTodayReviews(state, date, limit = state.settings.dailyReviewPages) { return Object.values(state.pages).filter(p => p.nextReview <= date).sort((a, b) => (priority[a.lastRating ?? 'good'] - priority[b.lastRating ?? 'good']) || daysBetween(a.nextReview, date) - daysBetween(b.nextReview, date) || a.page - b.page).slice(0, limit); }
  function generateDailyPlan(state, date) { const reviews = getTodayReviews(state, date, state.settings.allowExtraReviews ? 999 : state.settings.dailyReviewPages); const overdue = Object.values(state.pages).filter(p => p.nextReview < date).length; const wd = weekday(date); return { date, isMemorizationDay: isMemorizationDay(date, state.settings), newPages: nextNewPages(state, date), reviews, overdueCount: overdue, suggestion: wd === 5 ? 'اقتراح اختياري: تسميع أوجه الأسبوع الخمسة دون إلزام.' : wd === 6 ? 'يوم خفيف: راحة أو استماع أو مراجعة أخطاء دون عقوبة.' : undefined }; }
  function generateFullSchedule(state) { const plans = []; const sim = JSON.parse(JSON.stringify(state)); let date = state.settings.startDate, guard = 2000; while (sim.settings.lastMemorizedPage < sim.settings.totalPages && guard-- > 0) { plans.push(generateDailyPlan(sim, date)); if (isMemorizationDay(date, sim.settings)) sim.settings.lastMemorizedPage = Math.min(sim.settings.totalPages, sim.settings.lastMemorizedPage + sim.settings.newPagesPerDay); date = addDays(date, 1); } return plans; }
  function scheduleReview(page, rating, date, s) { return { ...page, reviewCount: page.reviewCount + 1, lastReviewed: date, lastRating: rating, nextReview: addDays(date, s.reviewIntervals[rating]), nearReviewStage: undefined }; }
  function recordReviewResult(state, page, rating, date, notes) { const current = state.pages[page] ?? { page, reviewCount: 0, nextReview: date }; return { ...state, pages: { ...state.pages, [page]: { ...scheduleReview(current, rating, date, state.settings), notes: notes ?? current.notes } }, history: [...state.history, { date, type: 'review', page, rating, notes }] }; }
  function completeNewMemorization(state, page, date, notes) { const next = Math.max(state.settings.lastMemorizedPage, page); const record = { page, firstMemorized: date, reviewCount: 0, lastRating: 'good', nextReview: addDays(date, 1), notes, nearReviewStage: 0 }; return { ...state, settings: { ...state.settings, lastMemorizedPage: next, memorizedPages: next }, pages: { ...state.pages, [page]: record }, history: [...state.history, { date, type: 'memorization', page, notes }] }; }
  function postponeDay(state, date, action = 'postponed') { return { ...state, postponedDates: [...new Set([...state.postponedDates, date])], history: [...state.history, { date, type: 'postpone', action }] }; }
  function reschedulePlan(state, settings) { return { ...state, settings: { ...state.settings, ...settings, reviewIntervals: { ...state.settings.reviewIntervals, ...settings.reviewIntervals } }, history: [...state.history, { date: new Date().toISOString().slice(0, 10), type: 'settings', notes: 'تحديث الإعدادات وإعادة توليد المستقبل دون حذف السجل' }] }; }
  let state = loadState(); let tab = 'dashboard'; const today = DEFAULT_START_DATE; const root = document.getElementById('root');
  function setState(s) { state = s; saveState(state); render(); }
  const actions = { start: () => setState({ ...state, started: true }), tab: d => { tab = d.tab || 'dashboard'; render(); }, theme: () => setState({ ...state, theme: state.theme === 'light' ? 'dark' : 'light' }), reset: () => setState(createInitialState()), postpone: () => setState(postponeDay(state, today)), complete: d => setState(completeNewMemorization(state, Number(d.page), today)), review: d => setState(recordReviewResult(state, Number(d.page), d.rating, today)), setting: d => { const input = document.querySelector(`#${d.input}`); setState(reschedulePlan(state, { [d.key]: Number(input.value) })); } };
  function bind(rootEl) { rootEl.querySelectorAll('[data-action]').forEach(b => b.onclick = () => actions[b.dataset.action]?.(b.dataset)); }
  function timer(minutes) { const id = `t${Math.random().toString(36).slice(2)}`; setTimeout(() => { const n = document.getElementById(id); if (!n) return; let sec = minutes * 60, run = false; n.querySelector('[data-start]').addEventListener('click', () => run = !run); n.querySelector('[data-reset]').addEventListener('click', () => { sec = minutes * 60; draw(); }); function draw() { n.querySelector('b').textContent = `${String(Math.floor(sec / 60)).padStart(2, '0')}:${String(sec % 60).padStart(2, '0')}`; } setInterval(() => { if (run && sec > 0) { sec--; draw(); } }, 1000); draw(); }); return `<div id="${id}" class="timer"><b></b><button data-start>بدء/إيقاف المؤقت</button><button data-reset>إعادة</button></div>`; }
  function onboarding() { return `<main class="card onboarding"><h1>إعداد خطة الحفظ</h1><p>تبدأ القيم الافتراضية في 01/09/2026 من الصفحة 160، مع حفظ الأحد إلى الخميس.</p><label>كم صفحة تحفظ؟<input id="memorizedPages" type="number" value="${state.settings.memorizedPages}"></label><button data-action="setting" data-input="memorizedPages" data-key="memorizedPages">حفظ العدد</button><label>آخر صفحة وصلت إليها<input id="lastMemorizedPage" type="number" value="${state.settings.lastMemorizedPage}"></label><button data-action="setting" data-input="lastMemorizedPage" data-key="lastMemorizedPage">حفظ الصفحة</button><button class="primary" data-action="start">ابدأ الخطة</button></main>`; }
  function reviewButtons(page) { return Object.keys(labels).map(r => `<button data-action="review" data-page="${page}" data-rating="${r}">${labels[r]}</button>`).join(''); }
  function render() { try { document.documentElement.dataset.theme = state.theme; const plan = generateDailyPlan(state, today), p = calculateProgress(state.settings), completion = calculateEstimatedCompletionDate(state, today); if (!state.started) { root.innerHTML = onboarding(); bind(root); return; } root.innerHTML = `<header><h1>رفيق الحفظ</h1><nav>${['dashboard:الرئيسية', 'today:خطة اليوم', 'calendar:التقويم', 'progress:التقدم', 'settings:الإعدادات'].map(x => { const [a, b] = x.split(':'); return `<button class="${tab === a ? 'active' : ''}" data-action="tab" data-tab="${a}">${b}</button>`; }).join('')}</nav></header><main id="page"></main>`; const page = document.getElementById('page'); if (tab === 'dashboard') page.innerHTML = `<section class="grid"><article class="hero"><h2>اليوم: ${arDate(today)}</h2><p>هجري: ${hijriDate(today)}</p><h3>حفظ جديد: ${plan.newPages.length ? `صفحة ${plan.newPages.join('، ')}` : 'لا حفظ جديد'}</h3><p>${plan.suggestion ?? ''}</p>${plan.newPages.map(pg => `<button class="primary" data-action="complete" data-page="${pg}">تم حفظ صفحة ${pg}</button>`).join('')}<button data-action="postpone">تأجيل اليوم</button></article><article><h3>مراجعة المساء</h3>${plan.reviews.map(r => `<div class="item">صفحة ${r.page} — ${quran.getPage(r.page).surah}<div>${reviewButtons(r.page)}</div></div>`).join('')}</article><article><h3>التقدم</h3><div class="bar"><span style="width:${p.percent}%"></span></div><p>${p.memorizedPages} / ${state.settings.totalPages} صفحة — ${p.percent}%</p><p>الختم المتوقع: ${completion} (تقديري ويتغير بالتأجيل)</p></article><article><h3>الجلسات</h3>${timer(state.settings.morningMinutes)}${timer(state.settings.eveningMinutes)}</article></section>`; if (tab === 'today') page.innerHTML = `<section class="grid"><article><h2>صباحًا — حفظ جديد</h2>${plan.newPages.map(pg => { const m = quran.getPage(pg); return `<div class="item">صفحة ${pg}، سورة ${m.surah}، جزء ${m.juz}<textarea placeholder="ملاحظات شخصية"></textarea><button>بدأت</button><button data-action="complete" data-page="${pg}">تم الحفظ</button><button data-action="postpone">أحتاج إعادة</button></div>`; }).join('')}${timer(state.settings.morningMinutes)}</article><article><h2>مساءً — مراجعة</h2>${plan.reviews.map(r => `<div class="item">صفحة ${r.page}، ${quran.getPage(r.page).surah}، جزء ${quran.getPage(r.page).juz}<small>آخر مراجعة: ${r.lastReviewed ?? '—'} | آخر تقييم: ${r.lastRating ? labels[r.lastRating] : '—'} | القادمة: ${r.nextReview}</small><div>${reviewButtons(r.page)}</div></div>`).join('')}</article></section>`; if (tab === 'calendar') page.innerHTML = `<section><h2>التقويم</h2><div class="calendar">${generateFullSchedule(state).slice(0, 35).map(d => `<button class="${d.isMemorizationDay ? 'mem' : 'rest'}"><b>${d.date}</b><span>${d.isMemorizationDay ? 'حفظ' : 'راحة'}</span><span>${d.reviews.length} مراجعات</span></button>`).join('')}</div></section>`; if (tab === 'progress') page.innerHTML = `<section><h2>إحصائيات التقدم</h2><div class="stats"><b>${p.percent}%</b><span>صفحات محفوظة: ${p.memorizedPages}</span><span>متبقي: ${p.remainingPages}</span><span>أجزاء مكتملة: ${p.completedJuz}</span><span>أيام ناجحة: ${state.history.filter(h => h.type === 'memorization').length}</span><span>مراجعات: ${state.history.filter(h => h.type === 'review').length}</span><span>الختم المتوقع: ${completion}</span></div><div class="chart">${state.history.filter(h => h.type === 'memorization').slice(-20).map((_, i) => `<i style="height:${20 + i * 4}px"></i>`).join('')}</div></section>`; if (tab === 'settings') page.innerHTML = `<section class="grid"><article><h2>الإعدادات</h2><label>المراجعة اليومية<input id="dailyReviewPages" type="number" value="${state.settings.dailyReviewPages}"></label><button data-action="setting" data-input="dailyReviewPages" data-key="dailyReviewPages">تحديث</button><label>حفظ يومي<input id="newPagesPerDay" type="number" value="${state.settings.newPagesPerDay}"></label><button data-action="setting" data-input="newPagesPerDay" data-key="newPagesPerDay">تحديث</button><label>آخر صفحة<input id="lastMemorizedPage" type="number" value="${state.settings.lastMemorizedPage}"></label><button data-action="setting" data-input="lastMemorizedPage" data-key="lastMemorizedPage">تحديث</button><button data-action="theme">الوضع الليلي</button><button data-action="reset">إعادة الضبط</button></article><article><h3>مصادر قابلة للاستبدال</h3><p>${quran.getTrustedSourceName()}</p><p>${audio.getSourceName()}</p><p>لا يوجد نص قرآن أو صور أو صوت مدمج غير موثوق.</p></article></section>`; bind(root); } catch (error) { root.innerHTML = `<main class="card onboarding"><h1>رفيق الحفظ</h1><p>حدث خطأ أثناء التشغيل، لكن الموقع نفسه تم تحميله. امسح بيانات الموقع أو أعد التحميل.</p><pre>${String(error)}</pre></main>`; console.error(error); } }
  if (!root) return;
  render();
})();
